INSERT INTO scenarios (id, name, description, target_hub_id, action_type, intensity, warning_threshold) VALUES ('METRO_PEAK_HOUR', 'Giờ cao điểm Ga Metro ĐHQG', 'Lượng sinh viên từ Metro đổ bộ vào khu đô thị ĐHQG tăng vọt, 12 lượt thuê xe liên tục diễn ra khiến trạm Metro cạn xe và phát cảnh báo thiếu xe.', 'hub-01', 'VEHICLE_DRAIN', 12, 2);
INSERT INTO scenarios (id, name, description, target_hub_id, action_type, intensity, warning_threshold) VALUES ('DORM_ZONE_OVERLOAD', 'Quá tải bãi đỗ KTX Khu B', 'Giờ tan tầm cuối ngày, 15 xe đồng loạt trả về KTX Khu B, đẩy tỷ lệ chiếm chỗ bãi đỗ vượt ngưỡng 95% và kích hoạt cảnh báo tràn bãi.', 'hub-04', 'DOCK_OVERFLOW', 15, 28);
INSERT INTO scenarios (id, name, description, target_hub_id, action_type, intensity, warning_threshold) VALUES ('CHARGING_LOAD_SURGE', 'Đột biến phụ tải sạc ban đêm', 'Hàng loạt xe dưới 50% pin cắm sạc đồng thời tại Trạm Bách Khoa và Thư viện, kích hoạt thuật toán cân bằng tải sạc thông minh.', 'hub-02', 'CHARGE_SURGE', 10, 8);
